import "@/App.css";
import axios from "axios";
import Hls from "hls.js";
import { 
  Play, Pause, Volume2, VolumeX, Maximize, Minimize, 
  Bell, BellOff, Clock, Tv, ChevronLeft, ChevronRight,
  Settings, Info, Radio
} from "lucide-react";
import { Toaster, toast } from "sonner";
import { Button } from "@/components/ui/button";
import { 
  Tooltip, 
  TooltipContent, 
  TooltipProvider, 
  TooltipTrigger 
} from "@/components/ui/tooltip";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
const API = `${BACKEND_URL}/api`;

// Detect Fire TV or Android TV
const isFireTV = () => {
  const ua = navigator.userAgent.toLowerCase();
  return ua.includes('aftb') || ua.includes('aftt') || ua.includes('afts') || 
         ua.includes('aftm') || ua.includes('aftrs') || ua.includes('amazon') ||
         ua.includes('silk') || ua.includes('fire');
};

const isAndroidTV = () => {
  const ua = navigator.userAgent.toLowerCase();
  return ua.includes('android') && (ua.includes('tv') || ua.includes('large'));
};

// Video Player Component
const VideoPlayer = ({ streamUrl, isPlaying, setIsPlaying }) => {
  const videoRef = useRef(null);
  const containerRef = useRef(null);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const controlsTimeoutRef = useRef(null);
  const hlsRef = useRef(null);

  useEffect(() => {
    const video = videoRef.current;
    if (!video || !streamUrl) return;

    const isTVDevice = isFireTV() || isAndroidTV();
    console.log('Device detection - Fire TV:', isFireTV(), 'Android TV:', isAndroidTV());

    const initPlayer = () => {
      // For Fire TV / Android TV - try native HLS first, then fallback to HLS.js with special config
      if (isTVDevice) {
        console.log('TV device detected, using optimized playback');
        
        // Try native HLS support first (works better on some TV devices)
        if (video.canPlayType('application/vnd.apple.mpegurl') || 
            video.canPlayType('application/x-mpegURL')) {
          console.log('Using native HLS playback for TV');
          video.src = streamUrl;
          video.addEventListener('loadedmetadata', () => {
            setIsLoading(false);
            if (isPlaying) video.play().catch(() => {});
          });
          video.addEventListener('error', (e) => {
            console.log('Native playback error, trying HLS.js:', e);
            initHlsPlayer(video, true);
          });
          return;
        }
        
        // Use HLS.js with TV-optimized settings
        initHlsPlayer(video, true);
      } else if (Hls.isSupported()) {
        initHlsPlayer(video, false);
      } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
        // Native HLS support (Safari)
        video.src = streamUrl;
        video.addEventListener('loadedmetadata', () => {
          setIsLoading(false);
          if (isPlaying) video.play().catch(() => {});
        });
      }
    };

    const initHlsPlayer = (videoElement, isTVMode) => {
      if (!Hls.isSupported()) {
        setError("HLS not supported on this device");
        return;
      }

      // TV-optimized config vs standard config
      const config = isTVMode ? {
        enableWorker: false, // Disable worker for TV devices
        lowLatencyMode: false,
        backBufferLength: 30,
        maxBufferLength: 60,
        maxMaxBufferLength: 120,
        capLevelToPlayerSize: true,
        capLevelOnFPSDrop: true,
        startLevel: 0, // Start with lowest quality for TV
        autoStartLoad: true,
        enableSoftwareAES: true,
        // Force lower quality for Fire TV
        abrMaxWithRealBitrate: true,
        maxLoadingDelay: 10,
        manifestLoadingTimeOut: 30000,
        manifestLoadingMaxRetry: 6,
        levelLoadingTimeOut: 30000,
        fragLoadingTimeOut: 60000,
        // Disable ABR to force consistent quality
        abrEwmaDefaultEstimate: 500000,
      } : {
        enableWorker: true,
        lowLatencyMode: false,
        backBufferLength: 90,
        maxBufferLength: 30,
        maxMaxBufferLength: 60,
        capLevelToPlayerSize: true,
        startLevel: -1,
        autoStartLoad: true,
        enableSoftwareAES: true,
        manifestLoadingTimeOut: 20000,
        manifestLoadingMaxRetry: 4,
        levelLoadingTimeOut: 20000,
        fragLoadingTimeOut: 30000,
      };

      const hls = new Hls(config);
      hlsRef.current = hls;
      
      hls.loadSource(streamUrl);
      hls.attachMedia(videoElement);
      
      hls.on(Hls.Events.MANIFEST_PARSED, (event, data) => {
        setIsLoading(false);
        setError(null);
        console.log('HLS manifest parsed, levels:', data.levels.length);
        
        // For TV devices, force lowest quality level
        if (isTVMode && data.levels.length > 0) {
          console.log('TV mode: Setting to lowest quality level');
          hls.currentLevel = 0;
        }
        
        if (isPlaying) {
          videoElement.play().catch((e) => console.log('Autoplay prevented:', e));
        }
      });

      hls.on(Hls.Events.ERROR, (event, data) => {
        console.log('HLS error:', data.type, data.details, data);
        if (data.fatal) {
          switch (data.type) {
            case Hls.ErrorTypes.NETWORK_ERROR:
              setError("Network error - retrying...");
              hls.startLoad();
              break;
            case Hls.ErrorTypes.MEDIA_ERROR:
              setError("Media error - recovering...");
              hls.recoverMediaError();
              break;
            default:
              setError("Stream unavailable");
              break;
          }
        }
      });

      hls.on(Hls.Events.LEVEL_SWITCHED, (event, data) => {
        console.log('Quality level switched to:', data.level);
      });

      hls.on(Hls.Events.FRAG_LOADED, () => {
        setIsLoading(false);
        setError(null);
      });
    };

    initPlayer();

    return () => {
      if (hlsRef.current) {
        hlsRef.current.destroy();
        hlsRef.current = null;
      }
    };
  }, [streamUrl]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    if (isPlaying) {
      video.play().catch(() => {});
    } else {
      video.pause();
    }
  }, [isPlaying]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    video.volume = isMuted ? 0 : volume;
  }, [volume, isMuted]);

  const handleMouseMove = useCallback(() => {
    setShowControls(true);
    if (controlsTimeoutRef.current) {
      clearTimeout(controlsTimeoutRef.current);
    }
    controlsTimeoutRef.current = setTimeout(() => {
      if (isPlaying) setShowControls(false);
    }, 3000);
  }, [isPlaying]);

  const toggleFullscreen = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    if (!document.fullscreenElement) {
      container.requestFullscreen().then(() => {
        setIsFullscreen(true);
      }).catch(() => {});
    } else {
      document.exitFullscreen().then(() => {
        setIsFullscreen(false);
      }).catch(() => {});
    }
  }, []);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  return (
    <div 
      ref={containerRef}
      className={`video-container ${showControls ? 'show-controls' : ''}`}
      onMouseMove={handleMouseMove}
      onMouseLeave={() => isPlaying && setShowControls(false)}
      data-testid="video-player-container"
    >
      <video
        ref={videoRef}
        className="w-full h-full"
        playsInline
        autoPlay
        muted={false}
        crossOrigin="anonymous"
        preload="auto"
        style={{ backgroundColor: '#000' }}
        data-testid="video-element"
      />
      
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/80">
          <div className="text-center">
            <div className="loading-spinner mx-auto mb-4"></div>
            <p className="text-gray-400 text-sm">Loading stream...</p>
          </div>
        </div>
      )}

      {error && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/80">
          <div className="text-center">
            <Radio className="w-12 h-12 text-[#FFC72C] mx-auto mb-4 animate-pulse" />
            <p className="text-white font-medium mb-2">{error}</p>
            <p className="text-gray-400 text-sm">Please try again later</p>
          </div>
        </div>
      )}

      {/* Player Controls */}
      <div className="player-controls" data-testid="player-controls">
        <div className="flex items-center justify-between">
          {/* Left controls */}
          <div className="flex items-center gap-4">
            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <button 
                    className="icon-btn"
                    onClick={() => setIsPlaying(!isPlaying)}
                    data-testid="play-pause-btn"
                    aria-label={isPlaying ? "Pause" : "Play"}
                  >
                    {isPlaying ? <Pause size={20} /> : <Play size={20} />}
                  </button>
                </TooltipTrigger>
                <TooltipContent>
                  <p>{isPlaying ? "Pause" : "Play"}</p>
                </TooltipContent>
              </Tooltip>
            </TooltipProvider>

            <div className="flex items-center gap-2">
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button 
                      className="icon-btn w-10 h-10"
                      onClick={() => setIsMuted(!isMuted)}
                      data-testid="mute-btn"
                      aria-label={isMuted ? "Unmute" : "Mute"}
                    >
                      {isMuted || volume === 0 ? <VolumeX size={18} /> : <Volume2 size={18} />}
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>
                    <p>{isMuted ? "Unmute" : "Mute"}</p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
              <input
                type="range"
                min="0"
                max="1"
                step="0.1"
                value={isMuted ? 0 : volume}
                onChange={(e) => {
                  setVolume(parseFloat(e.target.value));
                  setIsMuted(false);
                }}
                className="volume-slider"
                data-testid="volume-slider"
                aria-label="Volume"
              />
            </div>

            <div className="live-badge" data-testid="live-badge">
              LIVE
            </div>
          </div>

          {/* Right controls */}
          <div className="flex items-center gap-2">
            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <button 
                    className="icon-btn"
                    onClick={toggleFullscreen}
                    data-testid="fullscreen-btn"
                    aria-label={isFullscreen ? "Exit fullscreen" : "Fullscreen"}
                  >
                    {isFullscreen ? <Minimize size={20} /> : <Maximize size={20} />}
                  </button>
                </TooltipTrigger>
                <TooltipContent>
                  <p>{isFullscreen ? "Exit fullscreen" : "Fullscreen"}</p>
                </TooltipContent>
              </Tooltip>
            </TooltipProvider>
          </div>
        </div>
      </div>
    </div>
  );
};

// Program Card Component
const ProgramCard = ({ program, isActive, onSetReminder, hasReminder }) => {
  const formatTime = (isoString) => {
    const date = new Date(isoString);
    return date.toLocaleTimeString('en-US', { 
      hour: 'numeric', 
      minute: '2-digit',
      hour12: true,
      timeZone: 'America/Barbados'
    });
  };

  return (
    <div 
      className={`program-card ${isActive ? 'active' : ''}`}
      data-testid={`program-card-${program.id}`}
    >
      {program.image && (
        <div className="relative h-40 overflow-hidden">
          <img 
            src={program.image} 
            alt={program.title}
            className="w-full h-full object-cover"
          />
          {isActive && (
            <div className="absolute top-3 left-3">
              <span className="live-badge">NOW</span>
            </div>
          )}
        </div>
      )}
      <div className="p-4">
        <span className="category-badge mb-2">{program.category}</span>
        <h3 className="font-semibold text-white mt-2 mb-1 line-clamp-1" style={{ fontFamily: 'Oswald, sans-serif' }}>
          {program.title}
        </h3>
        <p className="text-gray-400 text-sm mb-3 line-clamp-2">{program.description}</p>
        <div className="flex items-center justify-between">
          <span className="time-display">
            {formatTime(program.start_time)} - {formatTime(program.end_time)}
          </span>
          {!isActive && (
            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <button 
                    className={`reminder-btn ${hasReminder ? 'active' : ''}`}
                    onClick={() => onSetReminder(program)}
                    data-testid={`reminder-btn-${program.id}`}
                    aria-label={hasReminder ? "Remove reminder" : "Set reminder"}
                  >
                    {hasReminder ? <BellOff size={14} /> : <Bell size={14} />}
                  </button>
                </TooltipTrigger>
                <TooltipContent>
                  <p>{hasReminder ? "Remove reminder" : "Set reminder"}</p>
                </TooltipContent>
              </Tooltip>
            </TooltipProvider>
          )}
        </div>
      </div>
    </div>
  );
};

// EPG Timeline Component
const EPGTimeline = ({ programs, currentProgram, onSetReminder, reminders }) => {
  const scrollRef = useRef(null);

  const scroll = (direction) => {
    if (scrollRef.current) {
      const scrollAmount = 320;
      scrollRef.current.scrollBy({
        left: direction === 'left' ? -scrollAmount : scrollAmount,
        behavior: 'smooth'
      });
    }
  };

  const formatTime = (isoString) => {
    const date = new Date(isoString);
    return date.toLocaleTimeString('en-US', { 
      hour: 'numeric', 
      minute: '2-digit',
      hour12: true,
      timeZone: 'America/Barbados'
    });
  };

  return (
    <div className="epg-timeline" data-testid="epg-timeline">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-white" style={{ fontFamily: 'Oswald, sans-serif' }}>
          TODAY'S SCHEDULE
        </h3>
        <div className="flex gap-2">
          <button 
            onClick={() => scroll('left')} 
            className="icon-btn w-10 h-10"
            data-testid="epg-scroll-left"
            aria-label="Scroll left"
          >
            <ChevronLeft size={18} />
          </button>
          <button 
            onClick={() => scroll('right')} 
            className="icon-btn w-10 h-10"
            data-testid="epg-scroll-right"
            aria-label="Scroll right"
          >
            <ChevronRight size={18} />
          </button>
        </div>
      </div>
      
      <div 
        ref={scrollRef}
        className="flex gap-3 overflow-x-auto hide-scrollbar pb-2"
      >
        {programs.map((program) => {
          const isCurrent = currentProgram?.id === program.id;
          const hasReminder = reminders.some(r => r.program_id === program.id);
          
          return (
            <div 
              key={program.id}
              className={`epg-item flex-shrink-0 ${isCurrent ? 'current' : ''}`}
              data-testid={`epg-item-${program.id}`}
            >
              <div className="flex items-center gap-2 mb-2">
                <span className="time-display text-xs">
                  {formatTime(program.start_time)}
                </span>
                {isCurrent && <span className="live-badge text-[10px]">LIVE</span>}
              </div>
              <h4 className="text-white font-medium text-sm mb-1 line-clamp-1">
                {program.title}
              </h4>
              <span className="text-gray-500 text-xs">{program.duration} min</span>
              {!isCurrent && (
                <button 
                  className={`mt-2 text-xs flex items-center gap-1 ${hasReminder ? 'text-[#FFC72C]' : 'text-gray-400 hover:text-white'}`}
                  onClick={() => onSetReminder(program)}
                  data-testid={`epg-reminder-${program.id}`}
                >
                  {hasReminder ? <BellOff size={12} /> : <Bell size={12} />}
                  {hasReminder ? 'Remove' : 'Remind'}
                </button>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

// Main App Component
function App() {
  const [epgData, setEpgData] = useState(null);
  const [streamInfo, setStreamInfo] = useState(null);
  const [reminders, setReminders] = useState([]);
  const [isPlaying, setIsPlaying] = useState(true);
  const [loading, setLoading] = useState(true);
  const [selectedProgram, setSelectedProgram] = useState(null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [isTVDevice, setIsTVDevice] = useState(false);

  // Fetch initial data
  useEffect(() => {
    // Detect if running on TV device
    const tvDevice = isFireTV() || isAndroidTV();
    setIsTVDevice(tvDevice);
    console.log('Is TV Device:', tvDevice);

    const fetchData = async () => {
      try {
        // Use TV-optimized stream for Fire TV/Android TV
        const streamEndpoint = tvDevice ? `${API}/stream-info/tv` : `${API}/stream-info`;
        
        const [epgRes, streamRes, remindersRes] = await Promise.all([
          axios.get(`${API}/epg`),
          axios.get(streamEndpoint),
          axios.get(`${API}/reminders`)
        ]);
        
        setEpgData(epgRes.data);
        setStreamInfo(streamRes.data);
        setReminders(remindersRes.data);
        setLoading(false);
        
        if (tvDevice) {
          console.log('TV device detected, using stream:', streamRes.data.stream_url);
        }
      } catch (error) {
        console.error('Error fetching data:', error);
        setLoading(false);
        toast.error('Failed to load data');
      }
    };

    fetchData();
  }, []);

  // Update time every minute
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentTime(new Date());
    }, 60000);
    return () => clearInterval(interval);
  }, []);

  // Check reminders
  useEffect(() => {
    const checkReminders = () => {
      const now = new Date();
      reminders.forEach(reminder => {
        const programStart = new Date(reminder.program_start);
        const diff = (programStart - now) / 1000 / 60; // minutes
        
        if (diff > 0 && diff <= 5 && !reminder.notified) {
          toast.info(`${reminder.program_title} starts in ${Math.ceil(diff)} minutes!`, {
            duration: 10000,
            icon: <Bell className="text-[#FFC72C]" />,
          });
        }
      });
    };

    const interval = setInterval(checkReminders, 60000);
    checkReminders();
    return () => clearInterval(interval);
  }, [reminders]);

  const handleSetReminder = async (program) => {
    const existingReminder = reminders.find(r => r.program_id === program.id);
    
    if (existingReminder) {
      try {
        await axios.delete(`${API}/reminders/${existingReminder.id}`);
        setReminders(reminders.filter(r => r.id !== existingReminder.id));
        toast.success('Reminder removed');
      } catch (error) {
        toast.error('Failed to remove reminder');
      }
    } else {
      try {
        const response = await axios.post(`${API}/reminders`, {
          program_id: program.id,
          program_title: program.title,
          program_start: program.start_time
        });
        setReminders([...reminders, response.data]);
        toast.success(`Reminder set for ${program.title}`);
      } catch (error) {
        if (error.response?.status === 400) {
          toast.info('Reminder already exists');
        } else {
          toast.error('Failed to set reminder');
        }
      }
    }
  };

  const formatCurrentTime = () => {
    return currentTime.toLocaleTimeString('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true,
      timeZone: 'America/Barbados'
    });
  };

  const getProgressPercent = () => {
    if (!epgData?.current_program) return 0;
    const start = new Date(epgData.current_program.start_time);
    const end = new Date(epgData.current_program.end_time);
    const now = new Date();
    const total = end - start;
    const elapsed = now - start;
    return Math.min(100, Math.max(0, (elapsed / total) * 100));
  };

  if (loading) {
    return (
      <div className="app-container flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="loading-spinner mx-auto mb-4"></div>
          <p className="text-gray-400">Loading CBC TV 8...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="app-container" data-testid="app-container">
      <Toaster 
        position="bottom-right" 
        theme="dark"
        toastOptions={{
          style: {
            background: '#0f111a',
            border: '1px solid #1e293b',
            color: '#fff',
          },
        }}
      />
      
      {/* Grain overlay for texture */}
      <div className="grain-overlay"></div>

      {/* Header */}
      <header className="app-header" data-testid="app-header">
        <div className="max-w-7xl mx-auto px-4 md:px-8 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-3">
                <Tv className="w-8 h-8 text-[#FFC72C]" />
                <div>
                  <h1 className="text-xl md:text-2xl font-bold text-white tracking-tight" style={{ fontFamily: 'Oswald, sans-serif' }}>
                    CBC TV 8
                  </h1>
                  <p className="text-xs text-gray-500 hidden sm:block">BARBADOS</p>
                </div>
              </div>
            </div>
            
            <div className="flex items-center gap-4">
              <div className="hidden md:flex flex-col items-end text-gray-400">
                <div className="flex items-center gap-2">
                  <Clock size={16} />
                  <span className="time-display">{formatCurrentTime()}</span>
                </div>
                <span className="text-[10px] text-gray-500">Barbados Time (AST)</span>
              </div>
              <div className="live-badge">
                LIVE
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 md:px-8">
        {/* Video Player Section */}
        <section className="hero-section fade-in" data-testid="hero-section">
          <div className="player-wrapper">
            <VideoPlayer 
              streamUrl={streamInfo?.stream_url ? `${BACKEND_URL}${streamInfo.stream_url}` : null}
              isPlaying={isPlaying}
              setIsPlaying={setIsPlaying}
            />
          </div>

          {/* Now Playing Info */}
          {epgData?.current_program && (
            <div className="now-playing mt-6" data-testid="now-playing">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <span className="live-badge">NOW PLAYING</span>
                    <span className="category-badge">{epgData.current_program.category}</span>
                  </div>
                  <h2 className="text-2xl md:text-3xl font-bold text-white mb-2" style={{ fontFamily: 'Oswald, sans-serif' }}>
                    {epgData.current_program.title}
                  </h2>
                  <p className="text-gray-400 text-sm md:text-base max-w-2xl">
                    {epgData.current_program.description}
                  </p>
                </div>
                <div className="flex items-center gap-3">
                  <Button 
                    variant="outline" 
                    className="bg-transparent border-gray-700 hover:bg-gray-800 hover:border-[#FFC72C]"
                    onClick={() => setSelectedProgram(epgData.current_program)}
                    data-testid="program-info-btn"
                  >
                    <Info size={16} className="mr-2" />
                    Info
                  </Button>
                </div>
              </div>
              
              {/* Progress bar */}
              <div className="mt-4">
                <div className="progress-bar">
                  <div 
                    className="progress-fill" 
                    style={{ width: `${getProgressPercent()}%` }}
                    data-testid="progress-bar"
                  ></div>
                </div>
                <div className="flex justify-between mt-2 text-xs text-gray-500">
                  <span>{new Date(epgData.current_program.start_time).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'America/Barbados' })}</span>
                  <span>{new Date(epgData.current_program.end_time).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'America/Barbados' })}</span>
                </div>
              </div>
            </div>
          )}
        </section>

        {/* EPG Timeline */}
        <section className="epg-section" data-testid="epg-section">
          <EPGTimeline 
            programs={epgData?.programs || []}
            currentProgram={epgData?.current_program}
            onSetReminder={handleSetReminder}
            reminders={reminders}
          />
        </section>

        {/* Up Next Section */}
        <section className="pb-12" data-testid="up-next-section">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-white" style={{ fontFamily: 'Oswald, sans-serif' }}>
              UP NEXT
            </h2>
            <span className="text-gray-500 text-sm">{epgData?.programs?.length || 0} programs today</span>
          </div>
          
          <ScrollArea className="w-full">
            <div className="flex gap-4 pb-4">
              {epgData?.programs?.slice(0, 8).map((program) => (
                <ProgramCard 
                  key={program.id}
                  program={program}
                  isActive={program.id === epgData?.current_program?.id}
                  onSetReminder={handleSetReminder}
                  hasReminder={reminders.some(r => r.program_id === program.id)}
                />
              ))}
            </div>
            <ScrollBar orientation="horizontal" />
          </ScrollArea>
        </section>
      </main>

      {/* Footer */}
      <footer className="app-footer" data-testid="app-footer">
        <div className="max-w-7xl mx-auto px-4 md:px-8">
          <div className="flex flex-col md:flex-row items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <Tv className="w-6 h-6 text-[#FFC72C]" />
              <span className="text-gray-400 text-sm">
                CBC TV 8 - Caribbean Broadcasting Corporation
              </span>
            </div>
            <p className="text-gray-600 text-xs">
              Free live television from Barbados
            </p>
          </div>
        </div>
      </footer>

      {/* Program Details Dialog */}
      <Dialog open={!!selectedProgram} onOpenChange={() => setSelectedProgram(null)}>
        <DialogContent className="bg-[#0f111a] border-gray-800 text-white max-w-lg">
          <DialogHeader>
            <DialogTitle className="text-xl" style={{ fontFamily: 'Oswald, sans-serif' }}>
              {selectedProgram?.title}
            </DialogTitle>
            <DialogDescription className="text-gray-400">
              {selectedProgram?.category} • {selectedProgram?.duration} minutes
            </DialogDescription>
          </DialogHeader>
          {selectedProgram?.image && (
            <img 
              src={selectedProgram.image} 
              alt={selectedProgram.title}
              className="w-full h-48 object-cover rounded-lg"
            />
          )}
          <p className="text-gray-300">{selectedProgram?.description}</p>
          <div className="flex items-center gap-2 text-sm text-gray-500">
            <Clock size={14} />
            <span>
              {selectedProgram && new Date(selectedProgram.start_time).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'America/Barbados' })}
              {' - '}
              {selectedProgram && new Date(selectedProgram.end_time).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'America/Barbados' })}
              {' (AST)'}
            </span>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

export default App;
